import Image from 'next/image'
import React from 'react'

type props = {
    params: Promise<{
        keyword: string
    }>
}

async function ImageComponent({ params }: props) {
    const { keyword = "dog" } = await params;

    return (
        <div className='border-1 relative w-128 h-128 mx-auto'>
            <Image
                src={`https://direct-img.link/${keyword}`}
                alt={keyword}
                fill
                priority
                quality={80}
                placeholder='blur'
                className='object-cover'
                blurDataURL='data:image/jpeg;base64,'
                sizes='(max-width:640px) 100vw, (max-width:1024px) 60vw, 45vw'
            />
        </div>
    )
}

export default ImageComponent
